import CoreData
import Foundation

/// Generates logs from CDRecurringSchedule rules.
///
/// Schedules are date-only: occurrence k falls on the start of its day, and is due once that day begins.
/// Each schedule logs at most once per period (day / calendar week / month). A period counts as taken if it
/// already has a log generated by the schedule (matched by `occurrenceDate`, so moving a log doesn't free its
/// period) or a skip marker (the user deleted that log).
struct RecurringEngine {
    let context: NSManagedObjectContext
    /// Used to snapshot today's rate when generating instances. When nil, instances use the schedule's frozen amount (e.g. tests).
    let currencyViewModel: CurrencyViewModel?
    private let calendar = Calendar.current

    init(context: NSManagedObjectContext, currencyViewModel: CurrencyViewModel? = nil) {
        self.context = context
        self.currencyViewModel = currencyViewModel
    }

    func generateDueTransactions(asOf now: Date = Date()) {
        LegacyRecurringMigration.run(in: context)

        let request = NSFetchRequest<CDRecurringSchedule>(entityName: "CDRecurringSchedule")
        let schedules = (try? context.fetch(request)) ?? []

        for schedule in schedules {
            var takenPeriods = takenPeriodStarts(for: schedule)
            for occurrence in occurrenceDates(for: schedule, through: now) {
                let period = periodStart(for: occurrence, interval: schedule.interval)
                guard !takenPeriods.contains(period) else { continue }
                makeInstance(from: schedule, on: occurrence)
                takenPeriods.insert(period)
            }
        }

        PersistenceController.shared.save(context)
    }

    // MARK: - Schedule lifecycle

    /// Creates a schedule from an existing log, starting on its date. The log becomes the first occurrence,
    /// so it isn't duplicated; it stays an ordinary log the user can edit or delete on its own.
    @discardableResult
    static func makeSchedule(
        from transaction: CDTransaction,
        interval: RecurringInterval,
        in context: NSManagedObjectContext
    ) -> CDRecurringSchedule {
        let schedule = CDRecurringSchedule(context: context)
        schedule.id = UUID()
        schedule.startDate = Calendar.current.startOfDay(for: transaction.date)
        schedule.intervalRaw = interval.rawValue
        schedule.amount = transaction.amount
        schedule.originalCurrencyRaw = transaction.originalCurrencyRaw
        schedule.originalAmount = transaction.originalAmount
        schedule.categoryRaw = transaction.categoryRaw
        schedule.merchant = transaction.merchant
        schedule.paymentMethodRaw = transaction.paymentMethodRaw
        schedule.notes = transaction.notes
        schedule.typeRaw = transaction.typeRaw
        schedule.createdAt = Date()

        transaction.generatedFromRecurringId = schedule.id
        transaction.occurrenceDate = transaction.date
        transaction.recurringIntervalRaw = interval.rawValue
        return schedule
    }

    /// Stops future logging. Past logs are untouched and keep their badge; only the schedule and its skip markers go.
    static func removeSchedule(_ schedule: CDRecurringSchedule, in context: NSManagedObjectContext) {
        let skippedRequest = NSFetchRequest<CDSkippedOccurrence>(entityName: "CDSkippedOccurrence")
        skippedRequest.predicate = NSPredicate(format: "groupId == %@", schedule.id as CVarArg)
        (try? context.fetch(skippedRequest))?.forEach { context.delete($0) }
        context.delete(schedule)
    }

    /// Records that a generated occurrence was deleted by the user so it isn't re-created.
    /// Returns the tombstone (so callers can remove it on undo), or nil if the transaction isn't a generated instance.
    @discardableResult
    static func recordSkippedOccurrence(for transaction: CDTransaction, in context: NSManagedObjectContext) -> CDSkippedOccurrence? {
        guard let scheduleId = transaction.generatedFromRecurringId else { return nil }
        let skipped = CDSkippedOccurrence(context: context)
        skipped.id = UUID()
        skipped.groupId = scheduleId
        // Use the scheduled date so a moved instance still tombstones the period it was generated for.
        skipped.date = transaction.occurrenceDate ?? transaction.date
        return skipped
    }

    // MARK: - Occurrences

    /// Due occurrence dates (start of day), from the schedule's start through `now`.
    func occurrenceDates(for schedule: CDRecurringSchedule, through now: Date) -> [Date] {
        let start = calendar.startOfDay(for: schedule.startDate)
        var dates: [Date] = []
        var index = 0
        while let date = occurrenceDate(index, from: start, interval: schedule.interval), date <= now {
            dates.append(date)
            index += 1
        }
        return dates
    }

    private func occurrenceDate(_ index: Int, from start: Date, interval: RecurringInterval) -> Date? {
        switch interval {
        case .daily:
            return calendar.date(byAdding: .day, value: index, to: start)
        case .weekly:
            return calendar.date(byAdding: .day, value: 7 * index, to: start)
        case .monthly:
            // Anchor on the 1st so short months don't drift the day (Jan 31 -> Feb 28 -> Mar 31).
            let startDay = calendar.component(.day, from: start)
            guard let monthStart = calendar.dateInterval(of: .month, for: start)?.start,
                  let targetMonth = calendar.date(byAdding: .month, value: index, to: monthStart),
                  let daysInMonth = calendar.range(of: .day, in: .month, for: targetMonth)?.count else { return nil }
            return calendar.date(byAdding: .day, value: min(startDay, daysInMonth) - 1, to: targetMonth)
        }
    }

    private func periodStart(for date: Date, interval: RecurringInterval) -> Date {
        let component: Calendar.Component
        switch interval {
        case .daily: component = .day
        case .weekly: component = .weekOfYear
        case .monthly: component = .month
        }
        return calendar.dateInterval(of: component, for: date)?.start ?? calendar.startOfDay(for: date)
    }

    /// Periods that already have a generated log or a skip marker for this schedule.
    private func takenPeriodStarts(for schedule: CDRecurringSchedule) -> Set<Date> {
        let interval = schedule.interval

        let txnRequest = NSFetchRequest<CDTransaction>(entityName: "CDTransaction")
        txnRequest.predicate = NSPredicate(format: "generatedFromRecurringId == %@", schedule.id as CVarArg)
        let logDates = ((try? context.fetch(txnRequest)) ?? []).map { $0.occurrenceDate ?? $0.date }

        let skippedRequest = NSFetchRequest<CDSkippedOccurrence>(entityName: "CDSkippedOccurrence")
        skippedRequest.predicate = NSPredicate(format: "groupId == %@", schedule.id as CVarArg)
        let skippedDates = ((try? context.fetch(skippedRequest)) ?? []).map(\.date)

        return Set((logDates + skippedDates).map { periodStart(for: $0, interval: interval) })
    }

    private func makeInstance(from schedule: CDRecurringSchedule, on date: Date) {
        let instance = CDTransaction(context: context)
        instance.id = UUID()
        instance.date = date
        instance.occurrenceDate = date
        applyAmountSnapshot(from: schedule, to: instance)
        instance.categoryRaw = schedule.categoryRaw
        instance.merchant = schedule.merchant
        instance.paymentMethodRaw = schedule.paymentMethodRaw
        instance.notes = schedule.notes
        instance.typeRaw = schedule.typeRaw
        instance.recurringIntervalRaw = schedule.intervalRaw
        instance.generatedFromRecurringId = schedule.id
        instance.createdAt = Date()
    }

    /// Copies the original-currency amount, then re-snapshots today's rate to compute `amount`.
    /// So a ฿16,000 rent schedule produces logs whose USD equivalent reflects each generation's FX rate.
    private func applyAmountSnapshot(from schedule: CDRecurringSchedule, to instance: CDTransaction) {
        instance.originalCurrencyRaw = schedule.originalCurrencyRaw
        instance.originalAmount = schedule.originalAmount
        if schedule.hasCurrencySnapshot, let vm = currencyViewModel {
            instance.amount = schedule.originalAmount * vm.rateToUSD(for: schedule.originalCurrency)
        } else {
            // Legacy schedule (no snapshot) or no view model available: copy frozen amount as-is.
            instance.amount = schedule.amount
        }
    }
}
